#!/usr/bin/env node
/**
 * OOXML round-trip baseline (plan §5.2, samples generated by decision D7).
 *
 * Runs the baseline suite with BASELINE_REPORT=1 so it writes
 * `fixtures/ooxml-baseline/{manifest,report}.json` and prints the drift against `report.golden.json`.
 * The comparison is informational: this script repeats the test exit code, and CI marks the step
 * `continue-on-error` — a baseline is a ratchet for humans, not a gate that blocks a release.
 *
 * Usage:
 *   pnpm baseline:roundtrip            # run + write report + print drift
 *   pnpm baseline:roundtrip --update   # additionally refresh report.golden.json
 */
import { spawnSync } from 'node:child_process';
import { join } from 'node:path';

const update = process.argv.includes('--update');
const bin = join(
  process.cwd(),
  'node_modules',
  '.bin',
  process.platform === 'win32' ? 'vitest.cmd' : 'vitest',
);

const result = spawnSync(bin, ['run', 'src/tools/baseline'], {
  stdio: 'inherit',
  env: {
    ...process.env,
    BASELINE_REPORT: '1',
    ...(update ? { BASELINE_UPDATE: '1' } : {}),
  },
});

if (result.error) {
  console.error('[baseline] failed to start vitest:', result.error.message);
  process.exit(1);
}

if (!update) {
  console.log(
    '[baseline] existing golden left untouched. Review fixtures/ooxml-baseline/report.json, then re-run with --update to accept the new numbers.',
  );
}

process.exit(result.status ?? 1);
